from pathlib import Path

ROOT = Path('/app') if Path('/app/scenario.json').exists() else Path(__file__).resolve().parents[1]
CONFIG_PATH = Path('/app/scenario.json') if Path('/app/scenario.json').exists() else ROOT / 'data/input.json'
CONFIG = json.loads(CONFIG_PATH.read_text())
INPUT = json.loads((ROOT / 'data/workload.json').read_text())
PARSER = argparse.ArgumentParser()
PARSER.add_argument('--stage', required=True, choices=CONFIG['stages'])
PARSER.add_argument('--output', default=str(ROOT / 'outputs'))
ARGS = PARSER.parse_args()
OUT = Path(ARGS.output)
OUT.mkdir(parents=True, exist_ok=True)
STAGE = ARGS.stage


def read_stage(name):
    record = json.loads((OUT / f'stage-{name}.json').read_text())
    if record['status'] != 'success' or record['stage'] != name:
        raise ValueError(f'invalid upstream stage: {name}')
    return record['result']


def previous():
    parents = CONFIG['dependencies'][STAGE]
    if len(parents) != 1:
        raise ValueError(f'{STAGE} requires an explicit parent selection')
    return read_stage(parents[0])


def write_json(name, value):
    (OUT / name).write_text(json.dumps(value, indent=2, allow_nan=False) + '\n')
    return value


def write_pickle(name, value):
    (OUT / name).write_bytes(pickle.dumps(value, protocol=4))


def write_csv(name, rows):
    with (OUT / name).open('w', newline='') as stream:
        writer = csv.DictWriter(stream, fieldnames=list(rows[0]))
        writer.writeheader()
        writer.writerows(rows)


def report(name, title, value):
    (OUT / name).write_text('<!doctype html><meta charset="utf-8"><title>' + html.escape(title) + '</title><h1>' + html.escape(title) + '</h1><pre>' + html.escape(json.dumps(value, indent=2)) + '</pre>\n')


def regression(rows):
    xs = [row[0] for row in rows]
    ys = [row[1] for row in rows]
    mean_x, mean_y = statistics.mean(xs), statistics.mean(ys)
    denominator = sum((x - mean_x) ** 2 for x in xs)
    if denominator <= 0:
        raise ValueError('training inputs have zero variance')
    weight = sum((x - mean_x) * (y - mean_y) for x, y in rows) / denominator
    return {'weight': weight, 'bias': mean_y - weight * mean_x}


def predict(model, x):
    return model['weight'] * x + model['bias']


def rmse(model, rows):
    return math.sqrt(statistics.mean((predict(model, x) - y) ** 2 for x, y in rows))


def require(condition, message):
    if not condition:
        raise ValueError(message)


def run_stage():
    started = time.time_ns()
    parents = CONFIG['dependencies'][STAGE]
    for parent in parents:
        read_stage(parent)
    result = compute()
    require(isinstance(result, dict) and result, 'activity produced no domain result')
    record = {
        'showcase': CONFIG['slug'], 'stage': STAGE, 'status': 'success',
        'validationMode': 'local-workload', 'startedAtUnixNs': started,
        'finishedAtUnixNs': time.time_ns(),
        'inputDigest': hashlib.sha256(json.dumps(INPUT, sort_keys=True).encode()).hexdigest(),
        'dependencies': parents, 'result': result,
    }
    write_json(f'stage-{STAGE}.json', record)
    print(json.dumps({'activity': STAGE, 'status': 'success', 'resultKeys': list(result)}))

def tokenize(text):
    return re.findall(r'[a-z0-9]+', text.lower())


def synthetic_dataset():
    if STAGE == 'define-schema':return {'required':['id','topic','question','answer'],'topics':INPUT['topics'],'minimumAnswerWords':3}
    if STAGE in ('batch-a','batch-b','batch-n'):
        schema=previous();offset={'batch-a':0,'batch-b':1,'batch-n':2}[STAGE]
        records=[]
        for index in range(INPUT['rowsPerBatch']):
            topic=schema['topics'][(index+offset)%len(schema['topics'])]
            records.append({'id':f'{offset}-{index}','topic':topic['name'],'question':f'How does {topic["name"]} work in example {index}?','answer':topic['explanation']})
        records.append({'id':'shared','topic':schema['topics'][0]['name'],'question':'Shared review question','answer':schema['topics'][0]['explanation']})
        records.append({'id':'invalid','topic':'unknown','question':'missing answer'})
        return {'records':records,'generator':'versioned schema templates; no LLM service'}
    if STAGE == 'filter':
        records=[row for parent in CONFIG['dependencies'][STAGE] for row in read_stage(parent)['records']]
        valid=[row for row in records if all(key in row for key in ('id','topic','question','answer')) and len(row['answer'].split())>=3]
        return {'records':valid,'rejected':len(records)-len(valid)}
    if STAGE == 'deduplicate':
        data=previous();unique={}
        for record in data['records']:
            key=' '.join(tokenize(record['question']))
            unique.setdefault(key,record)
        return {'records':list(unique.values()),'duplicatesRemoved':len(data['records'])-len(unique),'rejected':data['rejected']}
    if STAGE == 'quality-review':
        data=previous();topics={r['topic'] for r in data['records']}
        require(topics=={topic['name'] for topic in INPUT['topics']},'dataset topic coverage is incomplete')
        require(data['duplicatesRemoved']>=2 and data['rejected']==3,'deduplication/schema rejection checks failed')
        return {**data,'quality':{'rows':len(data['records']),'topics':len(topics),'duplicatesRemoved':data['duplicatesRemoved'],'schemaRejected':data['rejected']}}
    if STAGE == 'publish':
        data=previous();(OUT/'synthetic-dataset.jsonl').write_text(''.join(json.dumps(row)+'\n' for row in data['records']))
        return write_json('quality-report.json',data['quality'])
    raise ValueError(STAGE)


def compute():
    return synthetic_dataset()

if __name__ == '__main__':
    run_stage()
